CREATE OR REPLACE PROCEDURE sp(
    arg1 NUMBER,
    arg2 VARCHAR2,
    arg3 NUMBER,
    arg4 NUMBER
) IS
    v_total NUMBER := 0;
    v_max NUMBER;
BEGIN
    FOR r IN (
        SELECT "No", "Grape", "Winery", "Price", "Cases", "Score" 
        FROM "wine" 
        WHERE "Score" >= arg1
    ) LOOP
        v_total := v_total + NVL(r."Price", 0);

        IF instr(r."Grape", 'prefix_') = 1 THEN
            UPDATE "wine" SET "Price" = arg3 WHERE "No" = r."No";
        ELSIF r."No" < arg4 THEN
            DELETE FROM "wine" WHERE "No" = r."No";
        ELSIF r."Winery" = 'Twomey' THEN
            UPDATE "wine" SET "Price" = arg3 + NVL(r."Price", 0) WHERE "No" = r."No";
        ELSIF r."Cases" > r."Score" THEN
            UPDATE "wine" SET "Price" = arg3 + NVL(r."Price", 0) WHERE "No" = r."No";
        ELSE
            UPDATE "wine" SET "Price" = 3 * arg3 WHERE "No" = r."No";
        END IF;
    END LOOP;

    SELECT NVL(MAX("No"), 0) INTO v_max FROM "wine";

    INSERT INTO "wine" ("No", "Score", "Grape", "Price")
    VALUES (
        v_max + 1,
        arg1 + 1,
        'prefix_' || arg2,
        CASE WHEN v_total <= arg4 THEN arg3 ELSE arg3 + 1 END
    );
END;

